=== internal/cli/cli.go
     1	// Package cli parses ddkstat arguments and orchestrates a single run.
     2	package cli
     3	
     4	import (
     5		"flag"
     6		"fmt"
     7		"io"
     8	)
     9	
    10	const usage = "usage: ddkstat <summary|commands|targets|models|daily|failures> <log> [--target NAME] [--since YYYY-MM-DD] [--until YYYY-MM-DD]"
    11	
    12	// Exit codes, as declared in the architecture.
    13	const (
    14		exitRead  = 1
    15		exitUsage = 2
    16	)
    17	
    18	// reportNames lists the six reports in the order the architecture declares them.
    19	var reportNames = []string{"summary", "commands", "targets", "models", "daily", "failures"}
    20	
    21	// Options is the parsed ddkstat command line.
    22	type Options struct {
    23		Report    string
    24		Target    string
    25		HasTarget bool
    26		Since     string // YYYY-MM-DD or empty
    27		Until     string // YYYY-MM-DD or empty
    28		Log       string
    29	}
    30	
    31	// Parse reads the command line (program name excluded) into Options. The report comes first,
    32	// the three options may follow in any order, and exactly one log path comes last. Date values
    33	// are not validated here.
    34	func Parse(args []string) (Options, error) {
    35		fs := flag.NewFlagSet("ddkstat", flag.ContinueOnError)
    36		fs.SetOutput(io.Discard)
    37		target := fs.String("target", "", "")
    38		since := fs.String("since", "", "")
    39		until := fs.String("until", "", "")
    40		positional, err := parseInterspersed(fs, args)
    41		if err != nil {
    42			return Options{}, err
    43		}
    44		if len(positional) != 2 {
    45			return Options{}, fmt.Errorf("want one report and one log path, got %d positional arguments", len(positional))
    46		}
    47		if !isReport(positional[0]) {
    48			return Options{}, fmt.Errorf("unknown report %q", positional[0])
    49		}
    50		opts := Options{
    51			Report: positional[0],
    52			Target: *target,
    53			Since:  *since,
    54			Until:  *until,
    55			Log:    positional[1],
    56		}
    57		fs.Visit(func(f *flag.Flag) {
    58			if f.Name == "target" {
    59				opts.HasTarget = true
    60			}
    61		})
    62		return opts, nil
    63	}
    64	
    65	// isReport reports whether name is one of the six report names.
    66	func isReport(name string) bool {
    67		for _, r := range reportNames {
    68			if r == name {
    69				return true
    70			}
    71		}
    72		return false
    73	}
    74	
    75	// Run executes ddkstat with args (the program name excluded) and returns the process exit code.
    76	// Usage errors write the usage line to stderr and return 2; nothing reaches stdout.
    77	func Run(args []string, stdout, stderr io.Writer) int {
    78		opts, err := Parse(args)
    79		if err != nil {
    80			fmt.Fprintln(stderr, usage)
    81			return exitUsage
    82		}
    83		fmt.Fprintf(stderr, "ddkstat: report %q is not implemented yet\n", opts.Report)
    84		return exitRead
    85	}
    86	
    87	// parseInterspersed parses flags that may appear before, between, or after positional
    88	// arguments, as the flag package alone stops at the first positional. A bare "--" ends
    89	// option parsing, and everything after it is positional.
    90	func parseInterspersed(fs *flag.FlagSet, args []string) ([]string, error) {
    91		var positional []string
    92		for {
    93			if err := fs.Parse(args); err != nil {
    94				return nil, err
    95			}
    96			rest := fs.Args()
    97			if consumed := len(args) - len(rest); consumed > 0 && args[consumed-1] == "--" {
    98				return append(positional, rest...), nil
    99			}
   100			if len(rest) == 0 {
   101				return positional, nil
   102			}
   103			positional = append(positional, rest[0])
   104			args = rest[1:]
   105		}
   106	}
