     1	package cli
     2	
     3	import (
     4		"bytes"
     5		"testing"
     6	)
     7	
     8	func TestRunUsageErrorsExitTwoWithEmptyStdout(t *testing.T) {
     9		tests := []struct {
    10			name string
    11			args []string
    12		}{
    13			{name: "no arguments", args: nil},
    14			{name: "report only", args: []string{"summary"}},
    15			{name: "too many positionals", args: []string{"summary", "log.jsonl", "extra"}},
    16			{name: "unknown option", args: []string{"--bogus", "summary", "log.jsonl"}},
    17			{name: "help is an unknown option", args: []string{"-h"}},
    18			{name: "option missing its value", args: []string{"summary", "log.jsonl", "--target"}},
    19		}
    20		for _, tt := range tests {
    21			t.Run(tt.name, func(t *testing.T) {
    22				var stdout, stderr bytes.Buffer
    23				got := Run(tt.args, &stdout, &stderr)
    24				if got != 2 {
    25					t.Errorf("Run(%q) = %d, want 2", tt.args, got)
    26				}
    27				if stdout.Len() != 0 {
    28					t.Errorf("Run(%q) wrote %q to stdout, want nothing", tt.args, stdout.String())
    29				}
    30				if stderr.Len() == 0 {
    31					t.Errorf("Run(%q) wrote nothing to stderr, want the usage line", tt.args)
    32				}
    33			})
    34		}
    35	}
    36	
    37	func TestParseAcceptsEveryReport(t *testing.T) {
    38		for _, report := range []string{"summary", "commands", "targets", "models", "daily", "failures"} {
    39			t.Run(report, func(t *testing.T) {
    40				got, err := Parse([]string{report, "llm.jsonl"})
    41				if err != nil {
    42					t.Fatalf("Parse(%s, llm.jsonl) error: %v", report, err)
    43				}
    44				if got.Report != report {
