		return "", fmt.Errorf("%q is not a YYYY-MM-DD date", value)
	}
	if _, err := time.Parse(dateLayout, value); err != nil {
		return "", fmt.Errorf("%q is not a real calendar date", value)
	}
	return value, nil
}

