	}
	startedAt, err := requiredString(top, "started_at")
	if err != nil {
		return Record{}, err
	}
	status, err := requiredString(top, "status")
	if err != nil {
		return Record{}, err
	}
	job, _ := object(top["job"])
	command, err := requiredString(job, "command_name")
	if err != nil {
